function out = rtc7_build(varargin)
%RTC7_BUILD  RTC-7 manipulator -> Simscape Multibody model (MATLAB R2024a), demo motion, joint torques.
%
%   rtc7_build                 % import RTC-7.urdf, drive J1..J7 by the demo program, run, plot torques
%   rtc7_build('run', false)   % only build the model RTC7.slx (no simulation)
%   rtc7_build('speed', 2)     % the same path twice as fast
%   rtc7_build('drive', false) % plain import only: free model, joints without actuation
%
% Files next to this script (GENERATED by tools/urdf_export.py / tools/robot_dynamics.py):
%   RTC-7.urdf, meshes/*.stl          - geometry, masses, inertias, joints (zero pose = arm stretched up)
%   RTC-7-demo-traj.csv               - demo program, joint angles, rad, 30 fps
%   RTC-7-demo-torques-ref.csv        - the same motion, torques from the Python inverse dynamics
%   RTC-7-rated.csv                   - reducer rated torques
%
% What the model does: every joint is "Motion - provided by input" (angle from the trajectory, the
% derivatives by the 2nd-order filter of the Simulink-PS converter) and "Torque - automatically
% computed"; the actuator torque is sensed and logged (tau_J1 .. tau_J7) - inverse dynamics, the torque
% each drive has to give at the reducer output. Gravity -Z (Mechanism Configuration).
% NOT in the model: motor rotor inertia through the reducer, friction, cables (add on the joints:
% Internal Mechanics, or a reflected inertia block).
%
% Needs: MATLAB, Simulink, Simscape, Simscape Multibody (R2024a; R2022b+ should work too).

p = inputParser;
p.addParameter('run', true);
p.addParameter('drive', true);
p.addParameter('speed', 1.0);
p.addParameter('tau', 0.004);          % s, filter time constant of the angle inputs
p.parse(varargin{:});
o = p.Results;

here = fileparts(mfilename('fullpath'));
mdl = 'RTC7';
if bdIsLoaded(mdl), close_system(mdl, 0); end
if exist(fullfile(here, [mdl '.slx']), 'file'), delete(fullfile(here, [mdl '.slx'])); end
old = cd(here);
cleanup = onCleanup(@() cd(old));

fprintf('RTC-7: importing RTC-7.urdf ...\n');
smimport(fullfile(here, 'RTC-7.urdf'), 'ModelName', mdl);
if ~bdIsLoaded(mdl), load_system(mdl); end

% the root body must be welded to the world (some import paths add a 6-DOF joint)
six = find_system(mdl, 'LookUnderMasks', 'all', 'FollowLinks', 'on', 'Regexp', 'on', ...
                  'ReferenceBlock', '6-DOF Joint$');
for k = 1:numel(six)
    fprintf('  replacing the 6-DOF joint %s by a Weld Joint\n', six{k});
    replace_block(mdl, 'ReferenceBlock', get_param(six{k}, 'ReferenceBlock'), ...
                  'sm_lib/Joints/Weld Joint', 'noprompt');
end

J = find_joints(mdl);
fprintf('  joints: %s\n', strjoin(cellfun(@(b) get_param(b, 'Name'), J, 'UniformOutput', false), ', '));
if ~o.drive
    save_system(mdl, fullfile(here, [mdl '.slx']));
    fprintf('RTC-7: model %s.slx saved (no actuation).\n', mdl);
    out = [];
    return
end

% ---- trajectory: spline through the 30 fps samples -> 1 kHz, time scaled by "speed"
D = readmatrix(fullfile(here, 'RTC-7-demo-traj.csv'));
t = D(:, 1) / o.speed;
Q = D(:, 2:8);
ts = (0:0.001:t(end))';
Qs = interp1(t, Q, ts, 'spline');
T_end = ts(end);
for k = 1:7
    assignin('base', sprintf('rtc7_q%d', k), [ts, Qs(:, k)]);
end

% ---- per joint: input motion + computed torque + sensed torque, wired to the workspace
wiredAll = true;
for k = 1:7
    blk = J{k};
    ph0 = get_param(blk, 'PortHandles');
    set_by_pattern(blk, '^MotionActuationMode$', 'InputMotion');
    ph1 = get_param(blk, 'PortHandles');
    set_by_pattern(blk, '^TorqueActuationMode$', 'ComputedTorque');
    set_by_pattern(blk, '(?i)^Sense.*ActuatorTorque$', 'on');
    ph2 = get_param(blk, 'PortHandles');
    inQ = new_port(ph0, ph1);
    outT = new_port(ph1, ph2);
    pos = get_param(blk, 'Position');
    x0 = pos(1); y0 = pos(4) + 40;
    sys = get_param(blk, 'Parent');
    nm = get_param(blk, 'Name');
    src = add_block('simulink/Sources/From Workspace', [sys '/q_' nm], 'MakeNameUnique', 'on', ...
        'VariableName', sprintf('rtc7_q%d', k), 'Position', [x0 - 260, y0, x0 - 170, y0 + 30]);
    s2p = add_block('nesl_utility/Simulink-PS Converter', [sys '/S2PS_' nm], 'MakeNameUnique', 'on', ...
        'Position', [x0 - 130, y0, x0 - 100, y0 + 30]);
    set_by_pattern(s2p, '(?i)^Unit$', 'rad');
    set_by_pattern(s2p, '(?i)^FilteringAndDerivatives$', 'filter');
    set_by_pattern(s2p, '(?i)FilterOrder$', '2');
    set_by_pattern(s2p, '(?i)FilterTimeConstant$', num2str(o.tau));
    p2s = add_block('nesl_utility/PS-Simulink Converter', [sys '/PS2S_' nm], 'MakeNameUnique', 'on', ...
        'Position', [pos(3) + 100, y0, pos(3) + 130, y0 + 30]);
    set_by_pattern(p2s, '(?i)^Unit$', 'N*m');
    snk = add_block('simulink/Sinks/To Workspace', [sys '/tau_' nm], 'MakeNameUnique', 'on', ...
        'VariableName', ['tau_' nm], 'SaveFormat', 'Timeseries', ...
        'Position', [pos(3) + 170, y0, pos(3) + 260, y0 + 30]);
    phs = get_param(src, 'PortHandles'); phc = get_param(s2p, 'PortHandles');
    add_line(sys, phs.Outport(1), phc.Inport(1), 'autorouting', 'smart');
    php = get_param(p2s, 'PortHandles'); phk = get_param(snk, 'PortHandles');
    add_line(sys, php.Outport(1), phk.Inport(1), 'autorouting', 'smart');
    if isempty(inQ) || isempty(outT)
        wiredAll = false;
        fprintf(['  %s: could not tell the new q / t ports apart - connect by hand: S2PS_%s -> port q, ' ...
                 'port t -> PS2S_%s\n'], nm, nm, nm);
        continue
    end
    add_line(sys, phc.RConn(1), inQ, 'autorouting', 'smart');
    add_line(sys, outT, php.LConn(1), 'autorouting', 'smart');
end

set_param(mdl, 'StopTime', num2str(T_end), 'Solver', 'ode23t', 'MaxStep', '0.002', ...
          'RelTol', '1e-4', 'SimscapeLogType', 'none');
save_system(mdl, fullfile(here, [mdl '.slx']));
fprintf('RTC-7: model %s.slx saved; demo program %.1f s (speed x%g).\n', mdl, T_end, o.speed);
if ~o.run || ~wiredAll
    out = [];
    return
end

fprintf('RTC-7: simulating ...\n');
so = sim(mdl);
tau = zeros(numel(ts), 7);
for k = 1:7
    nm = get_param(J{k}, 'Name');
    ts_k = so.get(['tau_' nm]);
    tau(:, k) = interp1(ts_k.Time, squeeze(ts_k.Data), ts, 'linear', 'extrap');
end
out = struct('t', ts, 'q', Qs, 'tau', tau, 'speed', o.speed, 'sim', so);
assignin('base', 'rtc7', out);
plot_torques(here, ts, tau, o.speed);
end

% =====================================================================================================
function J = find_joints(mdl)
% Revolute joints of the import, ordered J1 .. J7 by their names (URDF joint names)
c = find_system(mdl, 'LookUnderMasks', 'all', 'FollowLinks', 'on', 'Regexp', 'on', ...
                'ReferenceBlock', 'Revolute Joint$');
J = cell(1, 7);
for i = 1:numel(c)
    tok = regexp(get_param(c{i}, 'Name'), 'J([1-7])(?!\d)', 'tokens', 'once');
    if ~isempty(tok), J{str2double(tok{1})} = c{i}; end
end
if any(cellfun(@isempty, J))
    error('rtc7_build:joints', ['Expected Revolute Joint blocks named J1..J7 after the import, found: %s'], ...
          strjoin(c', ', '));
end
end

function set_by_pattern(blk, pattern, value)
% set every dialog parameter whose name matches the pattern (names differ slightly between releases)
dp = fieldnames(get_param(blk, 'DialogParameters'));
hit = dp(~cellfun(@isempty, regexp(dp, pattern, 'once')));
if isempty(hit)
    warning('rtc7_build:param', '%s: no parameter matching %s. Parameters: %s', ...
            getfullname(blk), pattern, strjoin(dp', ', '));
    return
end
for i = 1:numel(hit)
    try
        set_param(blk, hit{i}, value);
    catch e
        warning('rtc7_build:param', '%s: %s = %s failed: %s', getfullname(blk), hit{i}, value, e.message);
    end
end
end

function h = new_port(a, b)
% the one physical port that appeared between two PortHandles snapshots (LConn or RConn)
h = [];
oldH = [a.LConn, a.RConn];
newH = [b.LConn, b.RConn];
d = setdiff(newH, oldH);
if numel(d) == 1
    h = d;
elseif numel(b.LConn) + numel(b.RConn) == numel(a.LConn) + numel(a.RConn) + 1
    % handles were regenerated: the new port is the extra one on the side that grew
    if numel(b.LConn) > numel(a.LConn), h = b.LConn(end); else, h = b.RConn(end); end
end
end

function plot_torques(here, ts, tau, speed)
R = readtable(fullfile(here, 'RTC-7-rated.csv'));
f = fullfile(here, 'RTC-7-demo-torques-ref.csv');
haveRef = exist(f, 'file') && speed == 1;
if haveRef, ref = readmatrix(f); end
figure('Name', 'RTC-7 joint torques (Simscape)', 'Color', 'w', 'Position', [80 60 900 900]);
for k = 1:7
    subplot(7, 1, k);
    plot(ts * speed, tau(:, k), 'LineWidth', 1.6, 'Color', [0.16 0.36 0.62]); hold on
    if haveRef, plot(ref(:, 1), ref(:, k + 1), '--', 'Color', [0.55 0.58 0.62]); end
    yline([-1 1] * R.T_rated_Nm(k), ':', 'Color', [0.4 0.4 0.4]);
    ylabel(sprintf('J%d, N·m', k)); grid on; box off
    if k == 1
        title('RTC-7: torque at the reducer output (Simscape), dotted = rated, dashed = Python reference');
    end
    fprintf('  J%d: peak %7.1f N·m (rated %g)\n', k, max(abs(tau(:, k))), R.T_rated_Nm(k));
end
xlabel('program time, s');
end
